#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> a = {1, 2, 3, 4, 5};
    std::vector<int> b = {10, 20, 30, 40, 50};
    std::vector<int> result(a.size());

    // 1. In-place transformation using unary std::transform
    std::transform(a.begin(), a.end(), a.begin(), [](int x) { return x * 2; });

    // 2. Binary std::transform: combine elements from a and b into result
    std::transform(a.begin(), a.end(), b.begin(), result.begin(), [](int x, int y) { return x + y; });

    // 3. Traversal using std::for_each to print results
    std::cout << "Result elements: ";
    std::for_each(result.cbegin(), result.cend(), [](int val) {
        std::cout << val << " ";
    });
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <array>
#include <algorithm>

bool greater10(int value) {
    return value > 10;
}

int main() {
    const std::array<int, 6> data = {4, 8, 15, 16, 23, 42};

    // 1. std::find
    auto it1 = std::find(data.cbegin(), data.cend(), 16);
    if (it1 != data.cend()) {
        std::cout << "Found 16 at index: " << (it1 - data.cbegin()) << "\n";
    }

    // 2. std::find_if
    auto it2 = std::find_if(data.cbegin(), data.cend(), greater10);
    if (it2 != data.cend()) {
        std::cout << "First value > 10: " << *it2 << " at index " << (it2 - data.cbegin()) << "\n";
    }

    // 3. std::find_if_not
    auto it3 = std::find_if_not(data.cbegin(), data.cend(), greater10);
    if (it3 != data.cend()) {
        std::cout << "First value <= 10: " << *it3 << " at index " << (it3 - data.cbegin()) << "\n";
    }

    return 0;
}

#include <iostream>
#include <array>
#include <algorithm>

int main() {
    std::array<int, 6> a = {16, 2, 77, 40, 120, 5};

    // 1. Sort ascending
    std::sort(a.begin(), a.end());

    std::cout << "Sorted: ";
    for (int n : a) {
        std::cout << n << " ";
    }
    std::cout << "\n";

    // 2. Binary search on sorted range
    bool has40 = std::binary_search(a.cbegin(), a.cend(), 40);
    bool has99 = std::binary_search(a.cbegin(), a.cend(), 99);
    std::cout << "Contains 40? " << (has40 ? "Yes" : "No") << "\n";
    std::cout << "Contains 99? " << (has99 ? "Yes" : "No") << "\n";

    // 3. Quantifiers
    auto is_positive = [](int n) { return n > 0; };
    auto is_greater_than_100 = [](int n) { return n > 100; };
    auto is_negative = [](int n) { return n < 0; };

    std::cout << "All positive? " << (std::all_of(a.cbegin(), a.cend(), is_positive) ? "Yes" : "No") << "\n";
    std::cout << "Any > 100? " << (std::any_of(a.cbegin(), a.cend(), is_greater_than_100) ? "Yes" : "No") << "\n";
    std::cout << "None negative? " << (std::none_of(a.cbegin(), a.cend(), is_negative) ? "Yes" : "No") << "\n";

    return 0;
}
